"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[7228],{17228:function(n){n.exports=JSON.parse('{"content":"\\n<center>    \\n<BookCard \\n          cover=\\"/assets/snippets/books/malice.png\\"\\n          title=\\"악의\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"현대문학\\"\\n          publishedDate=\\"2008-07-25\\"\\n          isbn=\\"9788972754190\\"\\n          rating=5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n이 작품의 가장 큰 특징은 ```누가 범인인가```를 과감히 폐기하고, ```왜 범행을 저질렀는가```라는 질문을 집요하게 파고든다는 점이다.  \\n소설 초반에 범인이 누군지 밝혀지며, 독자들의 <mark>범인 찾기</mark>를 의도적으로 제거하여 독자의 시선을 <mark>동기 추적</mark>이라는 더 복잡하고 근원적인 미스터리로 강제 전환시킨다.  \\n<br>\\n전지적 작가 시점이 아닌, 두 인물의 기록을 교차 제시하는 독특한 형식으로 전개된다.  \\n범인의 ```수기```와 가가 형사의 ```수사 기록```의 교차는 <mark>기록</mark>이라는 행위 자체가 지닌 진실성과 허구성을 탐구하는 소설의 핵심 주제이다.  \\n독자는 두 개의 상반된 텍스트를 통해 기록된 진실 이면에 숨겨진 더 거대한 진실을 판별해야 한다.  \\n<br>\\n<mark>악의</mark>는 특정한 계기나 이유 없이, 오직 상대방의 존재 자체를 부정하고 파멸시키려는 순수한 증오를 의미한다.  \\n<br>\\n개인적으로 마음에 드는 작품이다."}')}}]);